export type JsonSymbolMcdocBlockStateKeys<CASE extends
  | 'map'
  | 'keys'
  | '%fallback'
  | '%none'
  | '%unknown' = 'map'> = CASE extends 'map'
  ? JsonMcdocBlockStateKeysDispatcherMap
  : CASE extends 'keys'
    ? JsonMcdocBlockStateKeysKeys
    : CASE extends '%fallback'
      ? JsonMcdocBlockStateKeysFallback
      : CASE extends '%none'
        ? JsonMcdocBlockStateKeysNoneType
        : CASE extends '%unknown' ? JsonMcdocBlockStateKeysFallbackType : never
